def default_get(self, fields):
    res = super().default_get(fields)
    if 'company_id' in fields and not res['company_id']:
        res['company_id'] = self.env.company.id
    return res

def _check_company_consistency(self):
    for rule in self:
        route = rule.route_id
        if route.company_id and route.company_id not in rule.company_id.parent_ids:
            raise ValidationError(_(
                "Rule %(rule)s belongs to %(rule_company)s while the route belongs to %(route_company)s.",
                rule=rule.display_name,
                rule_company=rule.company_id.display_name,
                route_company=route.company_id.display_name,
            ))

def _onchange_route(self):
    """ Ensure that the rule's company is the same than the route's company. """
    if self.route_id.company_id:
        self.company_id = self.route_id.company_id
    if self.picking_type_id.warehouse_id.company_id != self.route_id.company_id:
        self.picking_type_id = False

def _get_message_dict(self):
    """ Return a dict with the different possible message used for the
    rule message. It should return one message for each stock.rule action
    (except push and pull). This function is override in mrp and
    purchase_stock in order to complete the dictionary.
    """
    message_dict = {}
    source, destination, direct_destination, operation = self._get_message_values()
    if self.action in ('push', 'pull', 'pull_push'):
        suffix = ""
        if self.action in ('pull', 'pull_push') and direct_destination and not self.location_dest_from_rule:
            suffix = _("<br>The products will be moved towards <b>%(destination)s</b>, <br/> as specified from <b>%(operation)s</b> destination.", destination=direct_destination, operation=operation)
        if self.procure_method == 'make_to_order' and self.location_src_id:
            suffix += _("<br>A need is created in <b>%s</b> and a rule will be triggered to fulfill it.", source)
        if self.procure_method == 'mts_else_mto' and self.location_src_id:
            suffix += _("<br>If the products are not available in <b>%s</b>, a rule will be triggered to bring the missing quantity in this location.", source)
        message_dict = {
            'pull': _(
                'When products are needed in <b>%(destination)s</b>, <br> <b>%(operation)s</b> are created from <b>%(source_location)s</b> to fulfill the need. %(suffix)s',
                destination=destination,
                operation=operation,
                source_location=source,
                suffix=suffix,
            ),
            'push': _(
                'When products arrive in <b>%(source_location)s</b>, <br> <b>%(operation)s</b> are created to send them to <b>%(destination)s</b>.',
                source_location=source,
                operation=operation,
                destination=destination,
            ),
        }
    return message_dict

def _create_mto_rule_if_not_exist(self, vals):
    route_exists = self.env['stock.rule'].search_count([
        ('route_id', '=', vals.get('route_id', False)),
        ('location_src_id', '=', vals.get('location_src_id', False)),
        ('location_dest_id', '=', vals.get('location_dest_id', False)),
        ('picking_type_id', '=', vals.get('picking_type_id', False)),
        ('procure_method', '=', vals.get('procure_method', False)),
    ], limit=1)
    if not route_exists:
        self.env['stock.rule'].create(vals)

def _serialize_procurement_values(self, values):
    """Helper method to serialize procurement values for storage.

    This method handles the serialization of different types of values:
    - BaseModel instances are converted to their IDs
    - Datetime and Date fields are converted to strings
    - Other values are kept as is

    :param values: Dictionary of procurement values
    :return: Dictionary with serialized values
    """
    serialized = {}
    for key, value in values.items():
        if isinstance(value, models.BaseModel):
            serialized[key] = value.ids
        elif isinstance(value, (datetime.datetime, datetime.date)):
            serialized[key] = value.isoformat()
        elif isinstance(value, (fields.Datetime, fields.Date)):
            serialized[key] = fields.Datetime.to_string(value) if isinstance(value, fields.Datetime) else fields.Date.to_string(value)
        else:
            serialized[key] = value
    return serialized

def run(self, procurements, raise_user_error=True):
    """Fulfil `procurements` with the help of stock rules.

    Procurements are needs of products at a certain location. To fulfil
    these needs, we need to create some sort of documents (`stock.move`
    by default, but extensions of `_run_` methods allow to create every
    type of documents).

    :param procurements: the description of the procurement
    :type procurements: list of `~odoo.addons.stock.models.stock_rule.ProcurementGroup.Procurement`
    :param raise_user_error: will raise either an UserError or a ProcurementException
    :type raise_user_error: boolan, optional
    :raises UserError: if `raise_user_error` is True and a procurement isn't fulfillable
    :raises ProcurementException: if `raise_user_error` is False and a procurement isn't fulfillable
    """

    def raise_exception(procurement_errors):
        if raise_user_error:
            dummy, errors = zip(*procurement_errors)
            raise UserError('\n'.join(errors))
        else:
            raise ProcurementException(procurement_errors)
    actions_to_run = defaultdict(list)
    procurement_errors = []
    for procurement in procurements:
        procurement.values.setdefault('company_id', procurement.location_id.company_id)
        procurement.values.setdefault('priority', '0')
        procurement.values.setdefault('date_planned', procurement.values.get('date_planned', False) or fields.Datetime.now())
        if self._skip_procurement(procurement):
            continue
        rule = self._get_rule(procurement.product_id, procurement.location_id, procurement.values)
        if not rule:
            error = _('No rule has been found to replenish "%(product)s" in "%(location)s".\nVerify the routes configuration on the product.',
                product=procurement.product_id.display_name, location=procurement.location_id.display_name)
            procurement_errors.append((procurement, error))
        else:
            action = 'pull' if rule.action == 'pull_push' else rule.action
            actions_to_run[action].append((procurement, rule))

    if procurement_errors:
        raise_exception(procurement_errors)

    for action, procurements in actions_to_run.items():
        if hasattr(self.env['stock.rule'], '_run_%s' % action):
            try:
                getattr(self.env['stock.rule'], '_run_%s' % action)(procurements)
            except ProcurementException as e:
                procurement_errors += e.procurement_exceptions
        else:
            _logger.error("The method _run_%s doesn't exist on the procurement rules" % action)

    if procurement_errors:
        raise_exception(procurement_errors)
    return True

def _search_rule_for_warehouses(self, route_ids, packaging_uom_id, product_id, warehouse_ids, company_id, domain):
    domain = Domain(domain)
    if warehouse_ids:
        domain &= Domain('warehouse_id', 'in', [False, *warehouse_ids.ids])
    valid_route_ids = set()
    if route_ids:
        valid_route_ids |= set(route_ids.ids)
    if packaging_uom_id:
        packaging_routes = packaging_uom_id.package_type_id.route_ids
        valid_route_ids |= set(packaging_routes.ids)
    valid_route_ids |= set((product_id.route_ids | product_id.categ_id.total_route_ids).ids)
    if warehouse_ids:
        filter_function = partial(self._filter_warehouse_routes, product_id, warehouse_ids)
        valid_route_ids |= set(warehouse_ids.route_ids.filtered(filter_function).ids)
    if valid_route_ids:
        domain &= Domain('route_id', 'in', list(valid_route_ids))
    res = self.env["stock.rule"].sudo()._read_group(  # sudo() needed for cross company warehouse usage
        domain,
        groupby=["location_dest_id", "warehouse_id", "route_id"],
        aggregates=["id:recordset"],
        order="route_sequence:min, sequence:min",
    )
    rule_dict = defaultdict(OrderedDict)
    for group in res:
        rules = group[3]
        if filtered_rules := rules.filtered(lambda r: company_id and r.company_id == company_id):
            rules = filtered_rules

        rule_dict[group[0].id, group[2].id][group[1].id] = rules.sorted(lambda rule: (rule.route_sequence, rule.sequence))[0]
    return rule_dict

def _search_rule(self, route_ids, packaging_uom_id, product_id, warehouse_id, domain):
    """ First find a rule among the ones defined on the procurement
    group, then try on the routes defined for the product, finally fallback
    on the default behavior
    """
    Rule = self.env['stock.rule']
    res = self.env['stock.rule']
    domain = Domain(domain)
    if warehouse_id:
        domain &= Domain('warehouse_id', 'in', [False, warehouse_id.id])
    domain = domain.optimize(Rule)
    if route_ids:
        res = Rule.search(Domain('route_id', 'in', route_ids.ids) & domain, order='route_sequence, sequence', limit=1)
    if not res and packaging_uom_id:
        packaging_routes = packaging_uom_id.package_type_id.route_ids
        if packaging_routes:
            res = Rule.search(Domain('route_id', 'in', packaging_routes.ids) & domain, order='route_sequence, sequence', limit=1)
    if not res:
        product_routes = product_id.route_ids | product_id.categ_id.total_route_ids
        if product_routes:
            res = Rule.search(Domain('route_id', 'in', product_routes.ids) & domain, order='route_sequence, sequence', limit=1)
    if not res and warehouse_id:
        warehouse_routes = warehouse_id.route_ids
        if warehouse_routes:
            res = Rule.search(Domain('route_id', 'in', warehouse_routes.ids) & domain, order='route_sequence, sequence', limit=1)
    elif not res and not warehouse_id:
        res = Rule.search(domain, order='route_sequence, sequence', limit=1)
    return res

def _check_intercomp_location(self, locations):
    if locations.filtered(lambda location: location.usage == 'transit'):
        inter_comp_location = self.env.ref('stock.stock_location_inter_company', raise_if_not_found=False)
        return inter_comp_location and inter_comp_location.id in locations.ids

def run_scheduler(self, use_new_cursor=False, company_id=False):
    """ Call the scheduler in order to check the running procurements (super method), to check the minimum stock rules
    and the availability of moves. This function is intended to be run for all the companies at the same time, so
    we run functions as SUPERUSER to avoid intercompanies and access rights issues. """
    try:
        self._run_scheduler_tasks(use_new_cursor=use_new_cursor, company_id=company_id)
    except Exception:
        _logger.error("Error during stock scheduler", exc_info=True)
        raise
    return {}

def _get_orderpoint_domain(self, company_id=False):
    domain = [('trigger', '=', 'auto'), ('product_id.active', '=', True)]
    if company_id:
        domain += [('company_id', '=', company_id)]
    return domain

def on_change_type(self):
    if self.type == 'internal' and self.location:
        if self.location.type != 'storage':
            self.location = None
    elif self.location:
        if self.location.type != 'warehouse':
            self.location = None

def on_change_product(self):
    self.unit = None
    if self.product:
        self.unit = self.product.default_uom

def warehouse_location(self):
    if self.type == 'purchase':
        return self.location

def storage_location(self):
    if self.type == 'internal':
        return self.location

def search_rec_name(cls, name, clause):
    _, operator, value = clause
    if operator.startswith('!') or operator.startswith('not '):
        bool_op = 'AND'
    else:
        bool_op = 'OR'
    return [bool_op,
        ('location.rec_name', *clause[1:]),
        ('product.rec_name', *clause[1:]),
        ]

@Override
public void processNonCompliantStockLocationLine(
    StockRules stockRules, StockLocationLine stockLocationLine) throws AxelorException {

  if (stockRules == null) {
    return;
  }

  if (stockRules.getOrderAlertSelect().equals(StockRulesRepository.ORDER_ALERT_ALERT)) {
    this.generateAndSendMessage(stockRules);
    return;
  }

  StockLocation stockLocation = stockLocationLine.getStockLocation();

  if (stockLocation == null
      || !appSupplychainService.isApp("supplychain")
      || !stockRules
          .getOrderAlertSelect()
          .equals(StockRulesRepository.ORDER_ALERT_PURCHASE_ORDER)) {
    return;
  }

  Product product = stockLocationLine.getProduct();

  BigDecimal minReorderQty = getDefaultSupplierMinQty(product);
  BigDecimal qtyToOrder =
      stockRulesService.getQtyToOrder(stockLocationLine, stockRules, minReorderQty);
  Partner supplierPartner = product.getDefaultSupplierPartner();

  if (supplierPartner != null) {

    Company company = stockLocation.getCompany();
    LocalDate today = appBaseService.getTodayDate(company);
    PurchaseOrder purchaseOrder =
        purchaseOrderRepo.save(
            purchaseOrderCreateSupplychainService.createPurchaseOrder(
                AuthUtils.getUser(),
                company,
                null,
                supplierPartner.getCurrency(),
                today.plusDays(supplierPartner.getDeliveryDelay()),
                stockRules.getName(),
                null,
                stockLocation,
                today,
                partnerPriceListService.getDefaultPriceList(
                    supplierPartner, PriceListRepository.TYPE_PURCHASE),
                supplierPartner,
                null,
                null));

    purchaseOrder.addPurchaseOrderLineListItem(
        purchaseOrderLineService.createPurchaseOrderLine(
            purchaseOrder, product, null, null, qtyToOrder, product.getUnit()));

    purchaseOrderService.computePurchaseOrder(purchaseOrder);

    purchaseOrderRepo.save(purchaseOrder);

    if (stockRules.getAlert()) {
      generateAndSendMessage(stockRules);
    }
  }
}

public void generateAndSendMessage(StockRules stockRules) throws AxelorException {

  Template template = stockRules.getStockRuleMessageTemplate();

  if (template == null) {
    StockConfig stockConfig =
        stockConfigRepo
            .all()
            .filter(
                "self.company = ?1 AND self.stockRuleMessageTemplate IS NOT NULL",
                stockRules.getStockLocation().getCompany())
            .fetchOne();
    if (stockConfig != null) {
      template = stockConfig.getStockRuleMessageTemplate();
    } else {
      template =
          templateRepo
              .all()
              .filter(
                  "self.metaModel.fullName = ?1 AND self.isSystem != true",
                  StockRules.class.getName())
              .fetchOne();
    }
  }

  if (template == null) {
    throw new AxelorException(
        stockRules,
        TraceBackRepository.CATEGORY_CONFIGURATION_ERROR,
        I18n.get(COULD_NOT_FIND_ELIGIBLE_EMAIL_TEMPLATE_FOR_STOCK_RULES),
        stockRules.getId());
  }

  try {
    Message message = templateMessageService.generateAndSendMessage(stockRules, template);
    if (ObjectUtils.isEmpty(message.getToEmailAddressSet())
        && ObjectUtils.isEmpty(message.getReplyToEmailAddressSet())) {
      throw new AxelorException(
          stockRules,
          TraceBackRepository.CATEGORY_NO_VALUE,
          I18n.get(COULD_NOT_FIND_RECIPIENTS_FOR_MESSAGE_GENERATED_FROM_STOCK_RULES),
          stockRules.getId());
    }
  } catch (ClassNotFoundException | IOException e) {
    throw new AxelorException(e, TraceBackRepository.CATEGORY_CONFIGURATION_ERROR);
  }
}

protected BigDecimal getDefaultSupplierMinQty(Product product) {
  Partner defaultSupplierPartner = product.getDefaultSupplierPartner();
  if (appPurchaseService.getAppPurchase().getManageSupplierCatalog()) {
    List<SupplierCatalog> supplierCatalogList = product.getSupplierCatalogList();
    if (defaultSupplierPartner != null && supplierCatalogList != null) {
      for (SupplierCatalog supplierCatalog : supplierCatalogList) {
        if (supplierCatalog.getSupplierPartner().equals(defaultSupplierPartner)) {
          return supplierCatalog.getMinQty();
        }
      }
    }
  }
  return BigDecimal.ZERO;
}

def validate_parent_warehouse(self):
	warehouse = frappe.get_cached_value(
		"Warehouse", self.parent_warehouse, ["is_group", "company"], as_dict=True
	)
	if warehouse and (not warehouse.is_group or warehouse.company != self.company):
		frappe.throw(
			_("Parent Warehouse {0} must be a group warehouse of company {1}").format(
				frappe.bold(self.parent_warehouse), frappe.bold(self.company)
			)
		)

def validate_periods_and_dates(self):
	if cint(self.demand_number) <= 0:
		frappe.throw(_("Number of periods must be greater than zero"))

	for row in self.items:
		if row.delivery_date and getdate(row.delivery_date) < getdate(self.from_date):
			frappe.throw(
				_("Row #{0}: Delivery Date {1} cannot be before From Date {2}").format(
					row.idx, formatdate(row.delivery_date), formatdate(self.from_date)
				)
			)

def validate_stock_items(self):
	item_codes = {row.item_code for row in self.items + self.selected_items if row.item_code}
	if not item_codes:
		return

	non_stock_items = frappe.get_all(
		"Item", filters={"name": ["in", list(item_codes)], "is_stock_item": 0}, pluck="name"
	)
	if non_stock_items:
		frappe.throw(
			_("Only stock items can be forecast: {0}").format(
				", ".join(frappe.bold(item) for item in non_stock_items)
			)
		)

def validate_demand_qty(self):
	for row in self.items:
		if row.get("demand_qty") in (None, ""):
			frappe.throw(_("Row #{0}: Demand Qty is mandatory").format(row.idx), frappe.MandatoryError)

def generate_manual_demand(self):
	if not self.selected_items:
		return

	item_details_by_code = {
		item.name: item
		for item in frappe.get_all(
			"Item",
			filters={"name": ["in", [row.item_code for row in self.selected_items]]},
			fields=["name", "item_name", "stock_uom as uom"],
		)
	}
	ascii_items_by_lowercase_code = {}
	if frappe.db.db_type == "mariadb":
		# Unicode casefold does not always match MariaDB's collation.
		ascii_items_by_lowercase_code = {
			code.lower(): item for code, item in item_details_by_code.items() if code.isascii()
		}

	forecast_demand = []
	for row in self.selected_items:
		if row.item_code not in item_details_by_code:
			matching_item = None
			if row.item_code.isascii():
				matching_item = ascii_items_by_lowercase_code.get(row.item_code.lower())

			# Fall back to the database for other collation-equivalent Item codes.
			item_details_by_code[row.item_code] = matching_item or frappe.db.get_value(
				"Item", row.item_code, ["item_name", "stock_uom as uom"], as_dict=True
			)
		item_details = item_details_by_code[row.item_code]

		for index in range(self.demand_number):
			if self.frequency == "Monthly":
				delivery_date = add_to_date(self.from_date, months=index)
			else:
				delivery_date = add_to_date(self.from_date, weeks=index)

			forecast_demand.append(
				{
					"item_code": row.item_code,
					"delivery_date": delivery_date,
					"item_name": item_details.item_name,
					"uom": item_details.uom,
					"demand_qty": 1.0,
				}
			)

	for demand in forecast_demand:
		self.append("items", demand)

def generate_demand(self):
	self.set("items", [])
	self.generate_manual_demand()

def create_mps(source_name: str, target_doc: str | dict | Document | None = None):
	def postprocess(source, doc):
		doc.naming_series = "MPS.YY.-.######"

	doc = get_mapped_doc(
		"Sales Forecast",
		source_name,
		{
			"Sales Forecast": {
				"doctype": "Master Production Schedule",
				"validation": {"docstatus": ["=", 1], "status": ["=", "Planned"]},
				"field_map": {
					"name": "sales_forecast",
					"from_date": "from_date",
				},
			},
		},
		target_doc,
		postprocess,
	)

	return doc

def update_sales_forecast_status(sales_forecast):
	if not sales_forecast or frappe.db.get_value("Sales Forecast", sales_forecast, "docstatus") != 1:
		return

	status = (
		"MPS Generated"
		if frappe.db.exists("Master Production Schedule", {"sales_forecast": sales_forecast})
		else "Planned"
	)
	frappe.db.set_value("Sales Forecast", sales_forecast, "status", status)

def onload(self):
	self.set_onload(
		"enable_stock_reservation",
		frappe.db.get_single_value("Stock Settings", "enable_stock_reservation"),
	)

	if self.docstatus == 1:
		self.set_onload(
			"pending_work_order_qty",
			ProductionPlanWorkOrderQuantities(self.name).get_pending_quantities(self),
		)

def validate_raw_material_group_warehouse(self):
	if not self.raw_material_group_warehouse:
		return

	group = frappe.db.get_value(
		"Warehouse",
		{"name": self.raw_material_group_warehouse, "is_group": 1, "company": self.company},
		["lft", "rgt"],
		as_dict=True,
	)
	if not group:
		frappe.throw(
			_("{0} must be a group warehouse of company {1}.").format(
				frappe.bold(_("Raw Material Group Warehouse")), frappe.bold(self.company)
			)
		)

	if self.for_warehouse and not frappe.db.exists(
		"Warehouse",
		{"name": self.for_warehouse, "is_group": 0, "lft": (">", group.lft), "rgt": ("<", group.rgt)},
	):
		frappe.throw(
			_("For Warehouse {0} must be a non-group warehouse under {1}.").format(
				frappe.bold(self.for_warehouse), frappe.bold(self.raw_material_group_warehouse)
			)
		)

def enable_auto_reserve_stock(self):
	if self.is_new() and frappe.db.get_single_value("Stock Settings", "auto_reserve_stock"):
		self.reserve_stock = 1

def validate_material_request_type(self):
	for row in self.get("mr_items"):
		if row.from_warehouse and row.material_request_type != "Material Transfer":
			row.from_warehouse = ""

def validate_sales_orders(self, sales_order=None):
	sales_orders = []

	if sales_order:
		sales_orders.append(sales_order)
	else:
		sales_orders = [row.sales_order for row in self.sales_orders if row.sales_order]

	data = sales_order_query(filters={"company": self.company, "sales_orders": sales_orders})

	title = _("Production Plan Already Submitted")
	if not data and sales_orders:
		msg = _("No items are available in the sales order {0} for production").format(sales_orders[0])
		if len(sales_orders) > 1:
			sales_orders = ", ".join(sales_orders)
			msg = _("No items are available in sales orders {0} for production").format(sales_orders)

		frappe.throw(msg, title=title)

	data = [d[0] for d in data]

	for sales_order in sales_orders:
		if sales_order not in data:
			frappe.throw(
				_("No items are available in the sales order {0} for production").format(sales_order),
				title=title,
			)

def set_pending_qty_in_row_without_reference(self):
	"Set Pending Qty in independent rows (not from SO or MR)."
	if self.docstatus > 0:  # set only to initialise value before submit
		return

	for item in self.po_items:
		if not item.get("sales_order") or not item.get("material_request"):
			item.pending_qty = item.planned_qty

def calculate_total_planned_qty(self):
	self.total_planned_qty = 0
	for d in self.po_items:
		self.total_planned_qty += flt(d.planned_qty)

def validate_data(self):
	validated_boms = set()
	for d in self.get("po_items"):
		if not d.bom_no:
			frappe.throw(_("Please select BOM for Item in Row {0}").format(d.idx))
		elif (d.item_code, d.bom_no) not in validated_boms:
			validate_bom_no(d.item_code, d.bom_no)
			validated_boms.add((d.item_code, d.bom_no))

		if not flt(d.planned_qty):
			frappe.throw(
				_("Row #{0}: Planned Qty must be greater than 0 for Item {1}.").format(
					d.idx, frappe.bold(d.item_code)
				)
			)

def _rename_temporary_references(self):
	"""po_items and sub_assembly_items items are both constructed client side without saving.

	Attempt to fix linkages by using temporary names to map final row names.
	"""
	new_name_map = {d.temporary_name: d.name for d in self.po_items if d.temporary_name}
	actual_names = {d.name for d in self.po_items}

	for sub_assy in self.sub_assembly_items:
		if sub_assy.production_plan_item not in actual_names:
			sub_assy.production_plan_item = new_name_map.get(sub_assy.production_plan_item)

def get_open_sales_orders(self):
	"""Pull sales orders  which are pending to deliver based on criteria selected"""
	open_so = get_sales_orders(self)

	if open_so:
		self.add_so_in_table(open_so)
	else:
		frappe.msgprint(_("Sales orders are not available for production"))

def add_so_in_table(self, open_so):
	"""Add sales orders in the table"""
	self.set("sales_orders", [])

	for data in open_so:
		self.append(
			"sales_orders",
			{
				"sales_order": data.name,
				"sales_order_date": data.transaction_date,
				"customer": data.customer,
				"grand_total": data.base_grand_total,
			},
		)

def add_mr_in_table(self, pending_mr):
	"""Add Material Requests in the table"""
	self.set("material_requests", [])

	for data in pending_mr:
		self.append(
			"material_requests",
			{"material_request": data.name, "material_request_date": data.transaction_date},
		)

def combine_so_items(self):
	if self.combine_items and self.po_items and len(self.po_items) > 0:
		items = []
		for row in self.po_items:
			items.append(
				frappe._dict(
					{
						"parent": row.sales_order,
						"item_code": row.item_code,
						"warehouse": row.warehouse,
						"qty": row.pending_qty,
						"pending_qty": row.pending_qty,
						"conversion_factor": 1.0,
						"description": row.description,
						"bom_no": row.bom_no,
					}
				)
			)

		self.set("po_items", [])
		self.add_items(items)
	else:
		self.get_items()

def get_items(self):
	self.set("po_items", [])
	if self.get_items_from == "Sales Order":
		self.get_so_items()

	elif self.get_items_from == "Material Request":
		self.get_mr_items()

def add_items(self, items):
	refs = {}
	for data in items:
		if not data.pending_qty:
			continue

		item_details = get_item_details(data.item_code, throw=False)
		if self.combine_items:
			bom_no = item_details.get("bom_no")
			if data.get("bom_no"):
				bom_no = data.get("bom_no")

			if bom_no in refs:
				refs[bom_no]["so_details"].append(
					{"sales_order": data.parent, "sales_order_item": data.name, "qty": data.pending_qty}
				)
				refs[bom_no]["qty"] += data.pending_qty
				continue

			else:
				refs[bom_no] = {
					"qty": data.pending_qty,
					"po_item_ref": data.name,
					"so_details": [],
				}
				refs[bom_no]["so_details"].append(
					{"sales_order": data.parent, "sales_order_item": data.name, "qty": data.pending_qty}
				)

		bom_no = data.bom_no or item_details and item_details.get("bom_no") or ""
		if not bom_no:
			continue

		pi = self.append(
			"po_items",
			{
				"warehouse": data.warehouse,
				"item_code": data.item_code,
				"description": data.description or item_details.description,
				"stock_uom": item_details and item_details.stock_uom or "",
				"bom_no": bom_no,
				"planned_qty": data.pending_qty,
				"pending_qty": data.pending_qty,
				"planned_start_date": now_datetime(),
				"product_bundle_item": data.parent_item,
			},
		)
		pi._set_defaults()

		if self.get_items_from == "Sales Order":
			pi.sales_order = data.parent
			pi.sales_order_item = data.name
			pi.description = data.description

		elif self.get_items_from == "Material Request":
			pi.material_request = data.parent
			pi.material_request_item = data.name
			pi.description = data.description

	if refs:
		for po_item in self.po_items:
			po_item.planned_qty = refs[po_item.bom_no]["qty"]
			po_item.pending_qty = refs[po_item.bom_no]["qty"]
			po_item.sales_order = ""
		self.add_pp_ref(refs)

def add_pp_ref(self, refs):
	for bom_no in refs:
		for so_detail in refs[bom_no]["so_details"]:
			self.append(
				"prod_plan_references",
				{
					"item_reference": refs[bom_no]["po_item_ref"],
					"sales_order": so_detail["sales_order"],
					"sales_order_item": so_detail["sales_order_item"],
					"qty": so_detail["qty"],
				},
			)

def calculate_total_produced_qty(self):
	self.total_produced_qty = 0
	for d in self.po_items:
		self.total_produced_qty += flt(d.produced_qty)

	self.db_set("total_produced_qty", self.total_produced_qty, update_modified=False)

def update_produced_pending_qty(self, produced_qty, production_plan_item):
	for data in self.po_items:
		if data.name == production_plan_item:
			data.produced_qty = produced_qty
			data.pending_qty = flt(data.planned_qty - produced_qty)
			data.db_update()

	self.calculate_total_produced_qty()
	self.update_status_and_bin_qty()

def update_status_and_bin_qty(self):
	previous_status = self.status
	self.set_status()
	self.db_set("status", self.status)
	if previous_status != self.status and "Completed" in (previous_status, self.status):
		self.update_bin_qty()

def validate_sales_order_planned_qty(self):
	planned_qty = self.get_so_item_planned_qty()
	if not planned_qty:
		return

	already_planned = self.get_so_wise_planned_qty(list({key[0] for key in planned_qty}))
	so_items = {
		row.name: row
		for row in frappe.get_all(
			"Sales Order Item",
			filters={"name": ("in", [key[1] for key in planned_qty])},
			fields=["name", "item_code", "stock_qty", "stock_uom"],
		)
	}
	allowance = flt(
		frappe.db.get_single_value("Manufacturing Settings", "overproduction_percentage_for_sales_order")
	)
	precision = frappe.get_precision("Production Plan Item", "planned_qty")

	for (sales_order, so_item), qty in planned_qty.items():
		row = so_items[so_item]
		unplanned_qty = flt(
			flt(row.stock_qty) * (1 + allowance / 100) - flt(already_planned.get((sales_order, so_item))),
			precision,
		)
		if flt(qty, precision) > unplanned_qty:
			frappe.throw(
				_(
					"Cannot plan {0} {1} of Item {2} against Sales Order {3}. Only {4} {1} is left to plan."
				).format(
					qty, row.stock_uom, frappe.bold(row.item_code), sales_order, max(unplanned_qty, 0)
				),
				title=_("Sales Order Qty Exceeded"),
			)

def get_so_item_planned_qty(self):
	"""Planned qty per Sales Order line, excluding product bundle components."""
	planned_qty = {}
	for row in self.po_items:
		if row.sales_order and row.sales_order_item and not row.product_bundle_item:
			key = (row.sales_order, row.sales_order_item)
			planned_qty[key] = planned_qty.get(key, 0) + flt(row.planned_qty)

	return planned_qty

def update_stock_reservation(self):
	if not self.reserve_stock:
		return

	reserve_stock_for_production_plan(self)

def add_reference_to_raw_materials(self):
	for item in self.mr_items:
		if reference := next(
			(
				sa_item.name
				for sa_item in self.sub_assembly_items
				if sa_item.production_item == item.main_item_code and sa_item.bom_no == item.from_bom
			),
			None,
		):
			item.db_set("sub_assembly_item_reference", reference)
		elif (
			self.reserve_stock
			and item.main_item_code
			and item.from_bom
			and item.main_item_code != frappe.get_cached_value("BOM", item.from_bom, "item")
		):
			frappe.throw(
				_(
					"Sub assembly item references are missing. Please fetch the sub assemblies and raw materials again."
				)
			)

def update_sales_order(self):
	so_items = {
		(row.sales_order, row.sales_order_item)
		for row in self.po_items + self.prod_plan_references
		if row.sales_order and row.sales_order_item
	}
	if not so_items:
		return

	so_wise_planned_qty = self.get_so_wise_planned_qty(list({key[0] for key in so_items}))
	for key in so_items:
		frappe.db.set_value(
			"Sales Order Item", key[1], "production_plan_qty", flt(so_wise_planned_qty.get(key))
		)

def update_bin_qty(self, item_codes: set[str] | None = None):
	rows = [(d.item_code, d.warehouse) for d in self.mr_items]
	rows += [
		(d.production_item, d.fg_warehouse)
		for d in self.sub_assembly_items
		if d.type_of_manufacturing == "In House"
	]
	for item_code, warehouse in rows:
		if warehouse and (item_codes is None or item_code in item_codes):
			bin_name = get_or_make_bin(item_code, warehouse)
			bin = frappe.get_doc("Bin", bin_name, for_update=True)
			bin.update_reserved_qty_for_production_plan()

def delete_draft_work_order(self):
	for d in frappe.get_all(
		"Work Order", fields=["name"], filters={"docstatus": 0, "production_plan": ("=", self.name)}
	):
		frappe.delete_doc("Work Order", d.name)

def cancel_untouched_stock_reservations(self):
	sre_list = frappe.get_all(
		"Stock Reservation Entry",
		filters={
			"voucher_type": self.doctype,
			"voucher_no": self.name,
			"docstatus": 1,
			"status": ("in", ["Reserved", "Partially Reserved"]),
		},
		pluck="name",
	)
	for sre_name in sre_list:
		sre_doc = frappe.get_doc("Stock Reservation Entry", sre_name)
		sre_doc.flags.ignore_permissions = True
		sre_doc.cancel()

def set_status(self, close: bool | None = None, update_bin: bool = False):
	self.check_permission("write")

	if close is None and self.status == "Closed":
		return

	self.status = {0: "Draft", 1: "Submitted", 2: "Cancelled"}.get(self.docstatus)

	if close:
		self.db_set("status", "Closed")
		self.cancel_untouched_stock_reservations()
		self.update_bin_qty()
		return

	if self.total_produced_qty > 0:
		self.status = "In Process"
		if self.all_items_completed():
			self.status = "Completed"

	if self.status != "Completed":
		self.update_requested_status()
		self.update_ordered_status()

	if close is not None:
		self.db_set("status", self.status)

	if update_bin and self.docstatus == 1 and self.status != "Completed":
		self.update_bin_qty()

def update_ordered_status(self):
	for child_table in ["po_items", "sub_assembly_items"]:
		for item in self.get(child_table):
			if item.ordered_qty:
				self.status = "In Process"
				return

def update_requested_status(self):
	if self.mr_items and all(flt(d.requested_qty) >= flt(d.quantity) for d in self.mr_items):
		self.status = "Material Requested"

def validate_plan_is_open(self):
	status = (
		frappe.db.get_value("Production Plan", self.name, "status") if not self.is_new() else self.status
	)
	if status in ("Closed", "Completed"):
		frappe.throw(
			_("Production Plan {0} is {1}").format(frappe.bold(self.name), _(status)),
			frappe.InvalidStatusError,
		)

def make_work_order_for_finished_goods(self, wo_list, default_warehouses):
	items_data = self.get_production_items()

	for _key, item in items_data.items():
		if self.sub_assembly_items:
			item["use_multi_level_bom"] = 0

		set_default_warehouses(item, default_warehouses)
		work_order = self.create_work_order(item)
		if work_order:
			wo_list.append(work_order)

def make_work_order_for_subassembly_items(self, wo_list, subcontracted_po, default_warehouses):
	pending = ProductionPlanWorkOrderQuantities(self.name).get_pending_quantities(self)
	for row in self.sub_assembly_items:
		if row.type_of_manufacturing == "Subcontract":
			subcontracted_po.setdefault(row.supplier, []).append(row)
			continue

		if row.type_of_manufacturing == "Material Request":
			continue

		work_order_data = {
			"source_warehouse": frappe.get_value("BOM", row.bom_no, "default_source_warehouse"),
			"wip_warehouse": default_warehouses.get("wip_warehouse"),
			"fg_warehouse": default_warehouses.get("fg_warehouse"),
			"scrap_warehouse": default_warehouses.get("scrap_warehouse"),
			"company": self.get("company"),
		}

		self.prepare_data_for_sub_assembly_items(
			row, work_order_data, pending["production_plan_sub_assembly_item"][row.name]
		)

		if work_order_data.get("qty") <= 0:
			continue

		work_order = self.create_work_order(work_order_data)
		if work_order:
			wo_list.append(work_order)

def get_subcontracted_qty(self):
	po_item = frappe.qb.DocType("Purchase Order Item")
	return frappe._dict(
		(
			frappe.qb.from_(po_item)
			.select(po_item.production_plan_sub_assembly_item, Sum(po_item.fg_item_qty))
			.where((po_item.production_plan == self.name) & (po_item.docstatus < 2))
			.groupby(po_item.production_plan_sub_assembly_item)
		).run()
	)

def show_list_created_message(self, doctype, doc_list=None):
	if not doc_list:
		return

	frappe.flags.mute_messages = False
	msgprint(_("{0} created").format(get_filtered_list_link(doctype, doc_list)))

def validate_mr_subcontracted(self):
	for row in self.mr_items:
		if row.material_request_type == "Subcontracting":
			if not frappe.db.get_value("Item", row.item_code, "is_sub_contracted_item"):
				frappe.throw(
					_("Item {0} is not a subcontracted item").format(row.item_code),
					title=_("Invalid Item"),
				)

def make_material_request(self):
	self.load_saved_plan_for_material_request()
	self.validate_mr_subcontracted()

	"""Create Material Requests grouped by Sales Order and Material Request Type"""
	material_request_list = []
	material_request_map = {}
	draft_qty = self.get_draft_requested_qty()

	for item in self.mr_items:
		qty_to_request = get_qty_to_request(item, draft_qty)
		if qty_to_request <= 0:
			continue

		item_doc = frappe.get_cached_doc("Item", item.item_code)

		# a group warehouse cannot receive stock; it must never reach a Material Request line
		if item.warehouse and frappe.get_cached_value("Warehouse", item.warehouse, "is_group"):
			frappe.throw(
				_("Cannot create Material Request for item {0} in group warehouse {1}.").format(
					frappe.bold(item.item_code), frappe.bold(item.warehouse)
				)
			)

		material_request_type = item.material_request_type or item_doc.default_material_request_type

		# key for Sales Order:Material Request Type:Customer
		key = "{}:{}:{}".format(item.sales_order, material_request_type, "")
		schedule_date = item.schedule_date or add_days(nowdate(), cint(item_doc.lead_time_days))

		if key not in material_request_map:
			# make a new MR for the combination
			material_request_map[key] = frappe.new_doc("Material Request")
			material_request = material_request_map[key]
			material_request.update(
				{
					"transaction_date": nowdate(),
					"status": "Draft",
					"company": self.company,
					"material_request_type": material_request_type,
				}
			)
			material_request_list.append(material_request)
		else:
			material_request = material_request_map[key]

		# add item
		material_request.append(
			"items",
			{
				"item_code": item.item_code,
				"from_warehouse": item.from_warehouse
				if material_request_type == "Material Transfer"
				else None,
				"qty": qty_to_request,
				"uom": item.uom,
				"schedule_date": schedule_date,
				"warehouse": item.warehouse,
				"sales_order": item.sales_order,
				"production_plan": self.name,
				"material_request_plan_item": item.name,
				"project": frappe.db.get_value("Sales Order", item.sales_order, "project")
				if item.sales_order
				else None,
			},
		)

	if not material_request_list:
		msgprint(_("All items are already requested"))
		return

	for material_request in material_request_list:
		# submit
		material_request.flags.ignore_permissions = 1
		material_request.run_method("set_missing_values")

		material_request.save()
		if self.get("submit_material_request"):
			material_request.submit()

	frappe.flags.mute_messages = False

	if material_request_list:
		material_request_list = [
			get_link_to_form("Material Request", m.name) for m in material_request_list
		]
		msgprint(_("{0} created").format(comma_and(material_request_list)))
	else:
		msgprint(_("No material request created"))

def get_draft_requested_qty(self):
	mr_item = frappe.qb.DocType("Material Request Item")
	return frappe._dict(
		(
			frappe.qb.from_(mr_item)
			.select(mr_item.material_request_plan_item, Sum(mr_item.stock_qty))
			.where((mr_item.production_plan == self.name) & (mr_item.docstatus == 0))
			.groupby(mr_item.material_request_plan_item)
		).run()
	)

def set_sub_assembly_items_based_on_level(self, row, bom_data, manufacturing_type=None):
	"Modify bom_data, set additional details."
	is_group_warehouse = frappe.db.get_value("Warehouse", self.sub_assembly_warehouse, "is_group")

	for data in bom_data:
		data.qty = data.stock_qty
		data.production_plan_item = row.name
		data.schedule_date = row.planned_start_date
		data.type_of_manufacturing = manufacturing_type or (
			"Subcontract" if data.is_sub_contracted_item else "In House"
		)

		if not is_group_warehouse:
			data.fg_warehouse = self.sub_assembly_warehouse

		if not self.combine_sub_items:
			data.sales_order = row.sales_order
			data.sales_order_item = row.sales_order_item

def set_default_supplier_for_subcontracting_order(self):
	items = [
		d.production_item for d in self.sub_assembly_items if d.type_of_manufacturing == "Subcontract"
	]

	if not items:
		return

	default_supplier = frappe._dict(
		frappe.get_all(
			"Item Default",
			fields=["parent", "default_supplier"],
			filters={"parent": ("in", items), "default_supplier": ("is", "set")},
			as_list=1,
		)
	)

	if not default_supplier:
		return

	for row in self.sub_assembly_items:
		if row.type_of_manufacturing != "Subcontract":
			continue

		row.supplier = default_supplier.get(row.production_item)

def all_items_completed(self):
	all_items_produced = all(flt(d.planned_qty) - flt(d.produced_qty) < 0.000001 for d in self.po_items)
	if not all_items_produced:
		return False

	wo_status = frappe.get_all(
		"Work Order",
		filters={
			"production_plan": self.name,
			"status": ("not in", ["Closed", "Stopped"]),
			"docstatus": 1,
		},
		fields="status",
		pluck="status",
	)
	all_work_orders_completed = all(s == "Completed" for s in wo_status)
	return all_work_orders_completed

def get_mr_item_planned_qty_query(mr_item):
	plan_item = frappe.qb.DocType("Production Plan Item")
	return (
		frappe.qb.from_(plan_item)
		.select(Sum(plan_item.planned_qty))
		.where((plan_item.material_request_item == mr_item.name) & (plan_item.docstatus == 1))
	)

def get_planned_qty_by_order_row(plans):
	plan_item = frappe.qb.DocType("Production Plan Item")
	rows = (
		frappe.qb.from_(plan_item)
		.select(plan_item.parent, plan_item.sales_order_item, Sum(plan_item.planned_qty).as_("qty"))
		.where(plan_item.parent.isin(plans))
		.groupby(plan_item.parent, plan_item.sales_order_item)
	).run(as_dict=True)
	return {(row.parent, row.sales_order_item): flt(row.qty) for row in rows}

def get_qty_to_request(item, draft_qty):
	qty_to_request = flt(
		flt(item.quantity)
		- flt(item.requested_qty)
		- flt(draft_qty.get(item.name)) / (flt(item.conversion_factor) or 1),
		item.precision("quantity"),
	)
	if qty_to_request > 0 and frappe.get_cached_value("UOM", item.uom, "must_be_whole_number"):
		qty_to_request = ceil(qty_to_request)

	return qty_to_request

def get_uom_conversion_factor(item_code, uom):
	item = frappe.get_cached_value("Item", item_code, ["variant_of", "stock_uom"], as_dict=True)
	conversion_factor = frappe.db.get_value(
		"UOM Conversion Detail", {"parent": item_code, "uom": uom}, "conversion_factor"
	)
	if not conversion_factor and item.variant_of:
		conversion_factor = frappe.db.get_value(
			"UOM Conversion Detail", {"parent": item.variant_of, "uom": uom}, "conversion_factor"
		)

	return conversion_factor or get_uom_conv_factor(uom, item.stock_uom)

def _merge_subitem(item_details, d):
	if d.item_code in item_details:
		item_details[d.item_code].qty = item_details[d.item_code].qty + d.qty
		return

	if not d.conversion_factor and d.purchase_uom:
		d.conversion_factor = get_uom_conversion_factor(d.item_code, d.purchase_uom)
	item_details[d.item_code] = d

def _should_explode_subitem(d, include_subcontracted_items):
	return bool(
		(d.default_material_request_type in ["Manufacture", "Purchase"] and not d.is_sub_contracted)
		or (d.is_sub_contracted and include_subcontracted_items)
		or d.is_phantom_item
	)

def consolidate_subcontracted_po(subcontracted_po, subcontracted_qty):
	items_to_remove = defaultdict(list)
	for supplier, items in subcontracted_po.items():
		for item in items:
			ordered_qty = flt(subcontracted_qty.get(item.name))
			if flt(item.qty) <= ordered_qty:
				items_to_remove[supplier].append(item)
			elif ordered_qty:
				item.qty -= ordered_qty

		subcontracted_po[supplier] = [item for item in items if item not in items_to_remove[supplier]]
	return {key: value for key, value in subcontracted_po.items() if value}

def get_requested_sub_assemblies(doc):
	requested_sub_assemblies = {}
	for row in doc.get("sub_assembly_items") or []:
		row = frappe._dict(row)
		if row.type_of_manufacturing == "Material Request":
			requested_sub_assemblies.setdefault(row.production_plan_item, set()).add(
				(row.production_item, row.bom_no)
			)

	return requested_sub_assemblies

def round_up_whole_uom(quantity, uom):
	if uom and frappe.get_cached_value("UOM", uom, "must_be_whole_number"):
		return ceil(quantity)
	return quantity

def get_mr_purchase_uom(row):
	item_details = frappe.get_cached_value("Item", row.item_code, ["purchase_uom", "stock_uom"], as_dict=1)
	if (
		row.get("default_material_request_type") == "Purchase"
		and item_details.purchase_uom
		and item_details.purchase_uom != item_details.stock_uom
	):
		return item_details.purchase_uom

def _apply_minimum_order_qty(mr_items):
	for rows in _purchase_rows_by_item(mr_items).values():
		surplus_qty = 0.0
		for order_rows in _rows_by_sales_order(rows):
			surplus_qty = _apply_minimum_order_qty_to_order(order_rows, surplus_qty)

def _purchase_rows_by_item(mr_items):
	rows_by_item = defaultdict(list)
	for row in mr_items:
		if row.get("material_request_type") not in ("Purchase", "Subcontracting"):
			continue
		if flt(row.get("quantity")) <= 0:
			continue
		key = (
			row.get("item_code"),
			row.get("warehouse"),
			row.get("material_request_type"),
			row.get("supplier"),
		)
		rows_by_item[key].append(row)
	return rows_by_item

def _rows_by_sales_order(rows):
	rows_by_order = defaultdict(list)
	for row in rows:
		rows_by_order[row.get("sales_order") or ""].append(row)
	# Keep surplus allocation stable when upstream queries return orders in a different order.
	return [rows_by_order[sales_order] for sales_order in sorted(rows_by_order)]

def _cover_from_surplus(rows, surplus_qty):
	for row in rows:
		covered_qty = min(surplus_qty, _stock_quantity(row))
		if covered_qty <= 0:
			break
		_set_stock_quantity(row, _stock_quantity(row) - covered_qty)
		surplus_qty -= covered_qty

def _set_stock_quantity(row, stock_qty):
	conversion_factor = flt(row.get("conversion_factor")) or 1
	quantity = _quantity_in_purchase_uom(stock_qty, conversion_factor, stock_qty)
	if frappe.get_cached_value("UOM", row.get("uom"), "must_be_whole_number"):
		quantity = ceil(quantity)
	row["quantity"] = quantity

def _adjust_required_qty_for_uom(row, required_qty):
	if not row["purchase_uom"]:
		row["purchase_uom"] = row["stock_uom"]

	if row["purchase_uom"] != row["stock_uom"]:
		if not (row["conversion_factor"] or frappe.flags.show_qty_in_stock_uom):
			frappe.throw(
				_("UOM Conversion factor ({0} -> {1}) not found for item: {2}").format(
					row["purchase_uom"], row["stock_uom"], row.item_code
				)
			)

	return required_qty

def get_so_details(sales_order):
	return frappe.db.get_value(
		"Sales Order", sales_order, ["transaction_date", "customer", "grand_total"], as_dict=1
	)

def get_warehouse_list(warehouses):
	warehouse_list = []

	if isinstance(warehouses, str):
		warehouses = json.loads(warehouses)

	for row in warehouses:
		child_warehouses = frappe.db.get_descendants("Warehouse", row.get("warehouse"))
		if child_warehouses:
			warehouse_list.extend(child_warehouses)
		else:
			warehouse_list.append(row.get("warehouse"))

	return warehouse_list

def _authorize_mr_request(doc, warehouses=None):
	"""Scope a caller-supplied plan to what the caller may see; `doc` is often unsaved, so check only a real name.

	`warehouses` is accepted so the call site reads the same as on develop, where it also narrows
	the caller to their permitted companies. There is no Company Restriction on this branch.
	"""
	name = doc.get("name")
	if isinstance(name, str) and frappe.db.exists("Production Plan", name):
		frappe.has_permission("Production Plan", doc=name, throw=True)

	# Values arrive through frappe.parse_json, so container elements are untyped: a dict reaches
	# frappe.db.get_value() in its *name* position and becomes a filter.
	for row in _iter_mr_rows(doc):
		for fieldname in ("item_code", "warehouse", "bom_no", "sales_order", "uom", "purchase_uom"):
			value = row.get(fieldname)
			if value is not None and not isinstance(value, str):
				frappe.throw(_("Invalid {0}").format(fieldname), frappe.PermissionError)

def _iter_mr_rows(doc):
	for key in ("po_items", "items", "sub_assembly_items"):
		for row in doc.get(key) or []:
			if isinstance(row, dict):
				yield row

def _validate_group_warehouse_target(doc):
	# the group only scopes availability; raw materials still need a concrete
	# receiving warehouse, so for_warehouse is required once we generate items.
	if doc.get("raw_material_group_warehouse") and not doc.get("for_warehouse"):
		frappe.throw(
			_("{0} is required to get raw materials when {1} is set.").format(
				frappe.bold(_("For Warehouse")), frappe.bold(_("Raw Material Group Warehouse"))
			)
		)

def _aggregate_bin_details(bin_list):
	qty_fields = (
		"projected_qty",
		"actual_qty",
		"ordered_qty",
		"reserved_qty_for_production",
		"planned_qty",
	)
	aggregated = {field: 0 for field in qty_fields}
	for row in bin_list or []:
		for field in qty_fields:
			aggregated[field] += flt(row.get(field))
	return aggregated

def _get_transfer_locations(mr_items, warehouses, company):
	from erpnext.stock.doctype.pick_list.pick_list import get_available_item_locations

	required_qty_by_item = defaultdict(float)
	for item in mr_items:
		required_qty_by_item[item.get("item_code")] += max(
			0, flt(item.get("quantity")) * flt(item.get("conversion_factor"))
		)

	return {
		item_code: get_available_item_locations(
			item_code, warehouses, required_qty, company, ignore_validation=True
		)
		if required_qty > 0
		else []
		for item_code, required_qty in required_qty_by_item.items()
	}

def _transfer_from_locations(item, locations, new_mr_items, required_qty):
	precision = frappe.get_precision("Material Request Plan Item", "quantity")
	transfers_by_warehouse = {}
	for d in locations:
		if flt(required_qty, precision) <= 0:
			return required_qty

		quantity = flt(min(required_qty, d.get("qty")), precision)
		if quantity <= 0:
			continue
		d["qty"] -= quantity
		required_qty -= quantity

		warehouse = d.get("warehouse")
		if warehouse in transfers_by_warehouse:
			transfer = transfers_by_warehouse[warehouse]
			transfer["quantity"] = flt(transfer["quantity"] + quantity, precision)
			continue

		new_dict = copy.deepcopy(item)
		new_dict.update(
			{
				"quantity": quantity,
				"material_request_type": "Material Transfer",
				"uom": new_dict.get("stock_uom"),  # internal transfer should be in stock UOM
				"from_warehouse": warehouse,
				"conversion_factor": 1.0,
			}
		)
		transfers_by_warehouse[warehouse] = new_dict
		new_mr_items.append(new_dict)
	return required_qty

